const Fastify = require('fastify');
const { VaultDb } = require('./vaultDb');
const { verifyUser } = require('./auth');

const app = Fastify();

app.register(async function documentRoutes(subInstance) {
  subInstance.addHook('preHandler', async (req, reply) => {
    const user = await verifyUser(req);
    if (!user) return reply.status(401).send({ error: 'Unauthorized' });
    req.user = user;
  });

  subInstance.get('/api/v1/vaults/:vaultId/files/:fileId/content', async (req, reply) => {
    const { vaultId, fileId } = req.params;

    // Verify user access to the vault
    const userAccess = await VaultDb.vaultPermissions.findOne({
      where: { vaultId, userId: req.user.id }
    });

    if (!userAccess) {
      return reply.status(403).send({ error: 'Access denied to target vault' });
    }

    // Ensure the file strictly belongs to the specified vault
    const file = await VaultDb.files.findOne({
      where: { id: fileId, vaultId }
    });

    if (!file) {
      return reply.status(404).send({ error: 'File not found in the specified vault' });
    }

    return reply.send({ fileId: file.id, payload: file.encryptedData });
  });
});

app.listen({ port: 8092 });
